INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Parking', '1', '9 BIS', 'CUOTA DE RECUPERACIÓN', E'- El Arrendatario debe pagar al Arrendador una cuota mensual de $18,812.10 más IVA.\n- Este pago se realiza en la misma fecha que el pago de la renta.\n- La cuota se utiliza para cubrir los gastos de operación del estacionamiento del gimnasio.\n- El Arrendador debe emitir comprobantes fiscales digitales y complementos de pago según las leyes fiscales aplicables.', E'Durante el plazo de vigencia del Contrato, El Arrendatario se obliga a pagar al Arrendador de manera mensual y en la misma fecha en que sea exigible el importe que comprende la Renta, una Cuota de Recuperación por la cantidad de $18,812.10 (dieciocho mil ochocientos doce pesos 10/100 moneda nacional) más el I.V.A.\n\nLa cuota de recuperación será empleada para afrontar los gastos de operación que se generan en el estacionamiento por parte de los usuarios del gimnasio. El Arrendador se obliga a cumplir con las obligaciones en materia de expedición de comprobantes fiscales digitales por internet y de complementos de pago establecidas en las disposiciones fiscales aplicables.');
