INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('26109387-1c2f-45cc-b488-86e606cac680', 'Common Area Maintenance Charges', '9', '10 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord an additional 10% of the monthly rent for administration and maintenance costs.\n- This amount is subject to value-added tax (VAT).\n- The payment is calculated based on the current rent amount at the time the payment is due.', 'La Arrendataria se obliga cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 10% del importe de la renta mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('26109387-1c2f-45cc-b488-86e606cac680', 'Incremento de Renta', '4', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every January, starting from April 9, 2022, until 2023.\n- The increase is based on the change in the National Consumer Price Index (INPC) published by INEGI.\n- The comparison is made between the INPC two months before the lease start or last rent adjustment and two months before the new adjustment.\n- If the increase percentage is more than 8%, the maximum increase will be capped at 8%.', E'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses durante el mes de enero de cada año calendario, siendo el primer incremento hasta el 2023, contado a partir de la fecha que se indica del 9 de abril del 2022, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica:\n\nSe tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido  que si el porcentaje de incremento es mayor al 8% (ocho por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('26109387-1c2f-45cc-b488-86e606cac680', 'Late Fees', '15', '17', 'INTERESES MORATORIOS', E'- The tenant must make all payments on time as agreed in the contract.\n- If a payment is late, a late interest rate of 2% per month will be charged.\n- This interest applies to the total unpaid amount if the payment is delayed by more than 45 days.\n- The interest is calculated monthly for the duration of the delay, starting from the original due date until the payment is made.\n- The landlord is not required to accept a monthly payment if previous payments are not settled.\n- Any payments made by the tenant will first cover unpaid interest and then the oldest outstanding principal amounts.', E'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato, precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago los intereses moratorios que se calcularán como sigue:\nLa tasa de intereses moratorios será del 2% (dos por ciento) mensual. \n\nEsta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.\nLa Arrendadora no estará obligada a recibir el pago de una mensualidad, si no están cubiertas las anteriores y en todo caso las cantidades pagadas a cuenta por la Arrendataria se aplicarán primero a intereses vencidos y no pagados y después al principal de las prestaciones adeudadas comenzando por las más antiguas.');
