es La Viga","grid_full_address":"1188 Calzada De La Viga, 4PB Y 9PA, El Triunfo, Iztapalapa, Ciudad De México 09430","map_addr_1":"1188 Calzada De La Viga","map_addr_2":"4PB Y 9PA","map_city_state_zip":"El Triunfo, Iztapalapa, Ciudad De México 09430","grid_brand":"Planet Fitness","location_created_at":"2025-09-30 19:42:35","active_lease_count_over_time":51169,"location_count_over_time":57846,"remaining_rent_liability_over_time":51169,"base_rent_current_month":"342176.0000","cam_current_month":"34217.6000","base_rent_next_month":"342176.0000","cam_next_month":"34217.6000","base_rent_per_square_meter":"1921.80","cam_per_square_meter":"192.18","base_rent_per_year":"4106112.0000","cam_per_year":"410611.2000"}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('5a680ea5-1e57-46e2-b1e3-bf6072adf247', 'c0926b67-ae09-4c12-a53b-601421deaabb', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Cumbres La Viga Lease: Promotora del Río, S.A. de C.V. (04/15/2024 - 08/14/2039)', NULL, false, 'activo', 'Lease', NULL, '2024-11-15', '2024-05-28', '2039-08-14', NULL, false, NULL, NULL, 0, NULL, NULL, NULL, NULL, 183, 'Promotora del Río, S.A. de C.V.', NULL, NULL, 'Calzada de la Viga 1188', NULL, 'El Triunfo, Iztapalapa', 'Ciudad de México', '09340', 'MX', 'Arnoldo del Río Sandoval', NULL, 'selene.maldonado@dercalica.mx', 152, 'percent', NULL, NULL, 1026528, E'Las partes convienen que La Arrendataria dará a La Arrendadora, en calidad de rentas anticipadas, el importe equivalente a 3 (tres) meses de Renta Mensual señalada en el Apartado 11.-, más el impuesto al valor agregado correspondiente, como sigue: el equivalente 1 (un) mes de renta el día 28 de mayo del 2024 y 2 (dos) meses de Renta una vez subsanados los siguientes puntos:\n\ni) Entrega de dictamen estructural o memoria de cálculo\nii) Entrega de Proyectos\n\nLas Partes acuerdan que la Rentas Adelantadas se devengarán durante los primeros tres meses de operación del Local Comercial', 684352, false, '{"lease_total_rent_next_month":"376393.6000","total_monthly_rent":"376393.6000","annual_gross_rent":"4516723.2000","daily_gross_rent":"12374.58410959","recurring_rent_annual":"4516723.2000","lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"base_rent_current_month":"342176.0000","cam_current_month":"34217.6000","base_rent_next_month":"342176.0000","cam_next_month":"34217.6000","base_rent_per_square_meter":"1921.80","cam_per_square_meter":"192.18","base_rent_per_year":"4106112.0000","cam_per_year":"410611.2000"}'::jsonb);
