INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('5a680ea5-1e57-46e2-b1e3-bf6072adf247', 'Late Fees', '13', '15', 'INTERESES MORATORIOS', E'- The tenant must make all payments on time as agreed in the contract.\n- If the tenant is late on a payment, a late interest rate of 5% per month will be charged.\n- This interest applies if the payment is more than 45 days late.\n- The interest is calculated monthly for the entire period the payment is overdue.\n- The landlord is not required to accept a monthly payment if previous payments are not settled.\n- Any payments made will first cover unpaid interest, then the oldest outstanding principal amounts.', E'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato, precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago los intereses moratorios que se calcularán como sigue: La tasa de intereses moratorios será del 5% (cinco por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.\n\nLa Arrendadora no estará obligada a recibir el pago de una mensualidad, si no están cubiertas las anteriores y en todo caso las cantidades pagadas a cuenta por la Arrendataria se aplicarán primero a intereses vencidos y no pagados y después al principal de las prestaciones adeudadas comenzando por las más antiguas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('5a680ea5-1e57-46e2-b1e3-bf6072adf247', 'Incremento de Renta', '5', '4', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase starting from the 25th month, either on October 28, 2024, or the opening date, whichever comes first.\n- The increase is based on the change in the National Consumer Price Index (INPC) over the past 12 months.\n- If the INPC increase is more than 5%, the rent increase is capped at 5%, except in certain cases.\n- If the INPC increase is more than 8%, the rent will increase by the full percentage change of the INPC over the past 12 months.', E'Las Partes convienen que la Renta Mensual será incrementada a partir del mes 25 (veinticinco), a partir de la fecha que se indica al término del plazo de gracia (28 de octubre de 2024) o a la fecha de apertura, lo que ocurra primero, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: \n\nSe tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografia (INEGI), durante los últimos 12 (doce) meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido de que si el porcentaje de incremento es mayor al 5% (cinco por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual, salvo el caso previsto en el párrafo siguiente. \n\nSin perjucio de lo anterior, las Partes acuerdan que si el Índice Nacional de Precios al Consumidor (INPC) es mayor al 8% (ocho por ciento), el incremento será del porcentaje que haya variado el Indice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), durante los últimos 12 (doce) meses inmediatos anteriores al mes en que deba efectuarse el ajuste.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('5a680ea5-1e57-46e2-b1e3-bf6072adf247', 'Common Area Maintenance Charges', '7', '8 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord a fee for administration and maintenance, calculated as a percentage of the monthly rent plus VAT, as specified in Section 19 of the contract.\n- This fee is based on the current rent amount at the time of payment.\n- The Tenant cannot demand an account of how these fees are used or influence the management or maintenance of the shopping center.\n- The Landlord must use these funds to maintain, repair, and replace parts of the shopping center to keep it in good working condition.\n- If unforeseen events or force majeure limit the gym''s operation, the Tenant will pay 70% of the maintenance fee for the duration of the situation.', E'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al porcentaje señalado en el Apartado 19.- de la Carátula, del importe de la renta mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial; sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.\n\nEn caso fortuito y/o de fuerza mayor que limite la operación del gimnasio, la Arrendataria pagará a la Arrendadora el 70% (setenta por ciento) de la cuota de mantenimiento por todo el tiempo en que subsista esta situación.');
